"""
Calculator for KPI start/end points from SOAP and log files.

Uses parser functions (e.g. from point_parser_functions) to populate
start_point_entries and end_point_entries, then computes deltas.
"""
from taf.ul.oam_kpi_calculations.provider import Provider


class Calculator:
    def __init__(self, kpi_name, start_point_file_path, end_point_file_paths, bts_info):
        self.start_point_file_path = start_point_file_path
        self.end_point_file_paths = (
            end_point_file_paths if isinstance(end_point_file_paths, (list, tuple)) else [end_point_file_paths]
        )
        self.kpi_name = kpi_name
        self.kpi = Provider.provide(kpi_name=kpi_name)(bts_info=bts_info)

    def _get_point_timestamp(self, point_entries, index):
        """Get timestamp from point_entries: values()[index][0], or None if empty.
        index can be Index.FIRST (0) or Index.LAST (-1)."""
        values = list(point_entries.values())
        if not values:
            return None
        value_list = values[index]
        return value_list[0] if value_list else None

    def calculate(self, search_start_timestamp, search_end_timestamp):
        self.kpi.start_point.parser_function(
            file_path=self.start_point_file_path,
            kpi=self.kpi,
            search_start_timestamp=search_start_timestamp,
            search_end_timestamp=search_end_timestamp,
            **self.kpi.start_point.parser_kwargs,
        )

        for file_path in self.end_point_file_paths:
            self.kpi.end_point.parser_function(
                file_path, self.kpi, search_start_timestamp, search_end_timestamp, **self.kpi.end_point.parser_kwargs
            )

        for rmod_id, iteration_result in self.kpi.dict_results.items():
            iteration_result.start_point_timestamp = self._get_point_timestamp(
                iteration_result.start_point_entries,
                self.kpi.start_point.index
            )
            iteration_result.end_point_timestamp = self._get_point_timestamp(
                iteration_result.end_point_entries,
                self.kpi.end_point.index,
            )
            if iteration_result.start_point_timestamp is not None and iteration_result.end_point_timestamp is not None:
                iteration_result.delta = (
                    iteration_result.end_point_timestamp - iteration_result.start_point_timestamp
                )
            else:
                iteration_result.delta = None
            self.kpi.results.append(iteration_result.to_dict())
